function addPlan(){const name=newPlan.value.name.trim();if(!name){notice.value='プラン名を入力してください。';return}if(plans.value.some(p=>p.name.trim().toLocaleLowerCase()===name.toLocaleLowerCase())){notice.value='同じ名前のプランがすでに登録されています。';return}const counts=[newPlan.value.overhaulCount,newPlan.value.maintenanceCount,newPlan.value.inspectionCount];if(counts.some(n=>!Number.isInteger(n)||n<0)){notice.value='各回数は0以上の整数で入力してください。';return}const id=Math.max(0,...plans.value.map(p=>p.id))+1;plans.value.push({id,name,overhaulCount:newPlan.value.overhaulCount,maintenanceCount:newPlan.value.maintenanceCount,inspectionCount:newPlan.value.inspectionCount});newPlan.value={name:'',overhaulCount:1,maintenanceCount:2,inspectionCount:1};showPlanModal.value=false;notice.value='プランを追加しました。年間契約登録画面から選択できます。'}
