function setPage(p:Page){page.value=p;notice.value=''}
function addHistory(b:Bike,startDate:string,endDate:string,category:string,title:string,detail:string,memo=''){histories.value.unshift({id:Math.max(0,...histories.value.map(h=>h.id))+1,bikeId:b.id,startDate,date:endDate,category,title,detail,memo})}
function startWork(kind:'maintenance'|'event'|'overhaul',item:any){if(item.status==='完了'||item.status==='キャンセル')return;item.status='作業中';notice.value='作業中に変更しました。完了時に完了日と作業メモを登録してください。'}
function startCompletion(kind:'maintenance'|'event'|'overhaul',item:any){completionTarget.value={kind,id:item.id};completionMemo.value='';const suggested=item.endDate||(kind==='event'?item.inspectionDate:item.date);completionDate.value=suggested.replace(/\//g,'-')}
function confirmCompletion(){if(!completionTarget.value)return;const {kind,id}=completionTarget.value;const list:any=kind==='maintenance'?maintenance.value:kind==='event'?eventChecks.value:overhauls.value;const item=list.find((x:any)=>x.id===id);if(!item||item.status==='完了')return;const b=bikes.value.find(x=>x.id===item.bikeId);if(!b)return;const category=kind==='event'?'inspection':kind; if(remaining(b,category as 'maintenance'|'inspection'|'overhaul')<=0){notice.value=kind==='event'?'点検サポートの契約回数が残っていません。':kind==='maintenance'?'メンテナンスの契約回数が残っていません。':'オーバーホールの契約回数を使い切っています。';completionTarget.value=null;return}const startDate=kind==='event'?item.inspectionDate:item.date;const endDate=completionDate.value.replace(/-/g,'/');if(!completionDate.value||endDate<startDate){notice.value='完了日は開始日以降の日付を指定してください。';return}item.status='完了';item.endDate=endDate;if(kind==='event'){b.inspectionUsed++;addHistory(b,startDate,endDate,'点検サポート',item.name,item.memo,completionMemo.value);notice.value='点検サポートを完了し、点検回数を1回消費しました。'}else if(kind==='maintenance'){b.maintenanceUsed++;addHistory(b,startDate,endDate,'メンテナンス',item.title,item.detail,completionMemo.value);notice.value='メンテナンスを完了し、メンテナンス回数を1回消費しました。'}else{b.overhaulUsed++;b.overhaulCompleted=endDate;addHistory(b,startDate,endDate,'オーバーホール',item.title,item.detail,completionMemo.value);notice.value='オーバーホールを完了しました。メンテナンス予定はイベント・目標に合わせてスタッフが登録してください。'}completionTarget.value=null;completionMemo.value=''}
function addContract(){if(!contractForm.value.start.endsWith('-12-01')){notice.value='年間契約の開始日は12月1日にしてください。';return}const applicationDate=new Date(`${contractForm.value.applicationDate}T00:00:00`);const contractStartYear=Number(contractForm.value.start.slice(0,4));const contractReceptionDeadline=new Date(`${contractStartYear}-12-31T23:59:59`);if(!Number.isFinite(applicationDate.getTime())||applicationDate>contractReceptionDeadline){notice.value='年間契約の受付期限は契約開始年の12月31日です。';return}const assigned=staff.value.find(x=>x.shopId===contractForm.value.shopId);if(!staff.value.some(x=>x.shopId===contractForm.value.shopId&&x.name===contractForm.value.receptionist)&&assigned)contractForm.value.receptionist=assigned.name;const id=Math.max(0,...bikes.value.map(x=>x.id))+1;const f=contractForm.value;const start=f.start.replace(/-/g,'/');const year=Number(start.slice(0,4))+1;bikes.value.push({id,customer:f.customer,name:f.bikeName,maker:f.maker,model:f.model,year:f.year,serial:f.serial,planId:f.planId,contractStart:start,contractEnd:`${year}/11/30`,overhaulUsed:0,maintenanceUsed:0,inspectionUsed:0,overhaulCompleted:'',shopId:f.shopId,receptionist:f.receptionist});selectedBikeId.value=id;newOverhaulBike.value=id;newOverhaulReceptionDate.value=f.applicationDate;notice.value='年間契約を登録しました。次のステップとしてオーバーホールの受付・実施予定日を設定してください。';page.value='overhaul';showContractModal.value=false;showOverhaulModal.value=true}
function addShop(){if(!newShopName.value.trim())return;shops.value.push({id:Math.max(0,...shops.value.map(x=>x.id))+1,name:newShopName.value,address:newShopAddress.value,phone:newShopPhone.value});newShopName.value='';newShopAddress.value='';newShopPhone.value='';showShopModal.value=false;notice.value='店舗を登録しました。'}
function addStaff(){if(!newStaffName.value.trim())return;staff.value.push({id:Math.max(0,...staff.value.map(x=>x.id))+1,shopId:newStaffShop.value,name:newStaffName.value,role:'受付担当'});newStaffName.value='';showStaffModal.value=false;notice.value='受付担当者を登録しました。'}
function openEdit(kind:'maintenance'|'event'|'overhaul',item:any){editTarget.value={kind,id:item.id};editDate.value=(kind==='event'?item.inspectionDate:item.date).replace(/\//g,'-');editEndDate.value=(item.endDate||'').replace(/\//g,'-');editTitle.value=kind==='event'?item.name:item.title;editDetail.value=kind==='event'?item.memo:item.detail;editReceptionist.value=item.receptionist||'田中'}
function saveEdit(){if(!editTarget.value)return;const {kind,id}=editTarget.value;if(kind==='overhaul'){const itemBike=overhauls.value.find(x=>x.id===id);const contractBike=bikes.value.find(x=>x.id===itemBike?.bikeId);const contractYear=Number(contractBike?.contractStart.slice(0,4));if(!contractBike||!isOverhaulSeason(editDate.value,contractYear)||(editEndDate.value&&!isOverhaulSeason(editEndDate.value,contractYear))){notice.value='オーバーホールの実施予定日は契約開始年の11月1日〜翌年2月末の期間で設定してください。';return}}const list:any=kind==='maintenance'?maintenance.value:kind==='event'?eventChecks.value:overhauls.value;const item=list.find((x:any)=>x.id===id);if(!item)return;const date=editDate.value.replace(/-/g,'/');const endDate=editEndDate.value?editEndDate.value.replace(/-/g,'/'):'';if(endDate&&endDate<date){notice.value='完了日は開始日以降の日付にしてください。';return}if(kind==='event'){item.inspectionDate=date;item.endDate=endDate;item.name=editTitle.value;item.memo=editDetail.value}else{item.date=date;item.endDate=endDate;item.title=editTitle.value;item.detail=editDetail.value}item.receptionist=editReceptionist.value;editTarget.value=null;notice.value='予定内容を更新しました。契約回数は変更していません。'}
function isOverhaulSeason(value:string,contractYear:number){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(`${value}T00:00:00`);if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==value)return false;const start=new Date(`${contractYear}-11-01T00:00:00`);const end=new Date(contractYear+1,2,0,23,59,59,999);return d>=start&&d<=end}
function addOverhaul(){const b=bikes.value.find(x=>x.id===newOverhaulBike.value);if(!b)return;const receptionDate=new Date(`${newOverhaulReceptionDate.value}T00:00:00`);const contractYear=Number(b.contractStart.slice(0,4));const receptionDeadline=new Date(`${contractYear}-12-31T23:59:59`);if(!Number.isFinite(receptionDate.getTime())||receptionDate>receptionDeadline){notice.value='オーバーホールの受付期限は契約開始年の12月31日です。';return}if(!isOverhaulSeason(newOverhaulDate.value,contractYear)||(newOverhaulEndDate.value&&!isOverhaulSeason(newOverhaulEndDate.value,contractYear))){notice.value='オーバーホールの実施予定日は契約開始年の11月1日〜翌年2月末の期間で設定してください。';return}const plannedDate=new Date(`${newOverhaulDate.value}T00:00:00`);if(receptionDate>plannedDate){notice.value='受付日は実施予定日以前の日付にしてください。同日での受付・実施は可能です。';return}if(newOverhaulEndDate.value&&newOverhaulEndDate.value<newOverhaulDate.value){notice.value='完了予定日は開始予定日以降にしてください。';return}if(!newOverhaulTitle.value.trim()){notice.value='作業名を入力してください。';return}if(remaining(b,'overhaul')<=0){notice.value='この契約のオーバーホール残回数がありません。';return}overhauls.value.push({id:Math.max(0,...overhauls.value.map(x=>x.id))+1,bikeId:b.id,date:newOverhaulDate.value.replace(/-/g,'/'),endDate:newOverhaulEndDate.value.replace(/-/g,'/'),status:'予定',title:newOverhaulTitle.value,detail:newOverhaulDetail.value,shopId:b.shopId,receptionist:b.receptionist});showOverhaulModal.value=false;notice.value='オーバーホール予定を登録しました。実施完了までは契約回数を消費しません。'}
function addMaintenance(){const b=bikes.value.find(x=>x.id===newWorkBike.value);if(!b)return;if(remaining(b,'maintenance')<=0){notice.value='この契約のメンテナンス残回数がありません。';return}if(newWorkEndDate.value&&newWorkEndDate.value<newWorkDate.value){notice.value='完了予定日は開始予定日以降にしてください。';return}maintenance.value.push({id:Math.max(0,...maintenance.value.map(x=>x.id))+1,bikeId:b.id,date:newWorkDate.value.replace(/-/g,'/'),endDate:newWorkEndDate.value.replace(/-/g,'/'),status:'予定',title:newWorkTitle.value,detail:newWorkDetail.value,shopId:b.shopId,receptionist:b.receptionist});showMaintenanceModal.value=false;notice.value='メンテナンス計画を追加しました。実施完了までは回数を消費しません。'}
function addEvent(){const b=bikes.value.find(x=>x.id===newEventBike.value);if(!b||!newEventName.value.trim())return;if(newInspectionEndDate.value&&newInspectionEndDate.value<newInspectionDate.value){notice.value='点検完了予定日は開始予定日以降にしてください。';return}if(remaining(b,'inspection')<=0){notice.value='この契約の点検サポート残回数がありません。';return}eventChecks.value.push({id:Math.max(0,...eventChecks.value.map(x=>x.id))+1,bikeId:b.id,name:newEventName.value,eventDate:newEventDate.value.replace(/-/g,'/'),inspectionDate:newInspectionDate.value.replace(/-/g,'/'),endDate:newInspectionEndDate.value.replace(/-/g,'/'),status:'予定',memo:'目標イベントに向けた点検サポート',shopId:b.shopId,receptionist:b.receptionist});newEventName.value='';showEventModal.value=false;notice.value='目標イベントと点検予定を登録しました。'}
function sendMail(){showMail.value=false;notice.value=`${mailTarget.value} 様への「${mailKind.value}」を送信した想定のデモです（実際には送信されません）。`}
</script>
<template>
<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">R</div><div><strong>ROAD BIKE CARE</strong><small>メンテナンス管理</small></div></div>
