  <div class="nav-group"><div class="nav-group-title">ホーム</div><button class="nav-item" :class="{active:page==='dashboard'}" @click="setPage('dashboard')"><span class="nav-icon">▦</span>ダッシュボード</button></div>
  <div class="nav-group"><div class="nav-group-title">顧客・契約管理</div><button v-for="item in [{id:'bikes',label:'顧客・自転車一覧',icon:'🚴'},{id:'contracts',label:'年間契約登録',icon:'＋'}]" :key="item.id" class="nav-item" :class="{active:page===item.id}" @click="setPage(item.id as Page)"><span class="nav-icon">{{item.icon}}</span>{{item.label}}</button></div>
  <div class="nav-group"><div class="nav-group-title">顧客向けサービス業務</div><button v-for="item in [{id:'overhaul',label:'オーバーホール',icon:'⚙'},{id:'maintenance',label:'メンテナンス計画',icon:'◷'},{id:'events',label:'目標イベント・点検',icon:'◇'},{id:'history',label:'メンテナンス履歴',icon:'▤'}]" :key="item.id" class="nav-item" :class="{active:page===item.id}" @click="setPage(item.id as Page)"><span class="nav-icon">{{item.icon}}</span>{{item.label}}</button></div>
  <div class="nav-group"><div class="nav-group-title">顧客対応</div><button class="nav-item" :class="{active:page==='messages'}" @click="setPage('messages')"><span class="nav-icon">✉</span>連絡・メール管理</button></div>
  <div class="nav-group"><div class="nav-group-title">店舗運営・設定</div><button v-for="item in [{id:'shops',label:'店舗・担当者管理',icon:'⌂'},{id:'plans',label:'プラン設定',icon:'▣'}]" :key="item.id" class="nav-item" :class="{active:page===item.id}" @click="setPage(item.id as Page)"><span class="nav-icon">{{item.icon}}</span>{{item.label}}</button></div>
</template>
<template v-else><div class="nav-group"><div class="nav-group-title">お客様メニュー</div><button class="nav-item" :class="{active:page==='mypage'}" @click="setPage('mypage')"><span class="nav-icon">▣</span>マイページ</button></div></template>
<div class="sidebar-bottom"><div class="side-label">表示モード</div><button class="mode-switch" @click="role=role==='staff'?'customer':'staff';page=role==='customer'?'mypage':'dashboard'"><span>{{role==='staff'?'店舗スタッフ':'顧客マイページ'}}</span><span>切替 ↗</span></button><div class="user"><div class="avatar">店</div><div><b>{{role==='staff'?'店舗管理者':'山田 太郎'}}</b><small>{{role==='staff'?'スタッフアカウント':'顧客アカウント'}}</small></div></div></div></aside>
<main class="main"><header class="topbar"><div class="breadcrumb">ROAD BIKE CARE <span>/</span> {{({dashboard:'ダッシュボード',bikes:'顧客・自転車管理',contracts:'契約登録',shops:'店舗・担当者管理',plans:'プラン設定',overhaul:'オーバーホール',maintenance:'メンテナンス計画',events:'目標イベント・点検',history:'メンテナンス履歴',messages:'連絡・メール管理',mypage:'マイページ'} as Record<Page,string>)[page]}}</div><div class="top-actions"><span class="today">{{today}}</span><div class="avatar">店</div></div></header><div class="content"><div v-if="notice" class="notice"><span>{{notice}}</span><button @click="notice=''">×</button></div>
<template v-if="page==='dashboard'"><div class="page-heading"><div><p class="eyebrow">ROAD BIKE SERVICE OVERVIEW</p><h1>ダッシュボード</h1><p class="sub">年間契約・オーバーホール・目標イベントに向けた作業計画を管理します。</p></div><button class="primary" @click="setPage('maintenance')">メンテナンス計画を作成</button></div>
<div class="callout"><b>年間契約受付：12月1日〜12月31日 ／ 契約期間：12月1日〜翌年11月30日</b><p>オーバーホールは11月〜翌年2月末に実施（受付は12月31日まで）。メンテナンス・点検サポートは目標イベントに合わせて計画します。</p></div>
<div class="stats"><div class="stat-card"><div class="stat-top"><span>登録自転車数</span><span class="stat-icon blue">🚴</span></div><strong>{{bikes.length}}</strong><small>台</small></div><div class="stat-card"><div class="stat-top"><span>未完了の作業予定</span><span class="stat-icon purple">⚙</span></div><strong>{{upcomingCount}}</strong><small>件</small></div><div class="stat-card"><div class="stat-top"><span>案内待ち</span><span class="stat-icon orange">✉</span></div><strong>{{pendingCount}}</strong><small>件</small></div><div class="stat-card"><div class="stat-top"><span>作業履歴</span><span class="stat-icon green">✓</span></div><strong>{{completedCount}}</strong><small>件</small></div></div>
<section class="panel"><div class="panel-head"><div><h2>直近の作業予定</h2><p>オーバーホール・メンテナンス・イベント前点検</p></div></div><div class="table-wrap"><table><thead><tr><th><button class="sort-header" @click="toggleListSort('dashboard','customer')">顧客 {{sortLabel('dashboard','customer')}}</button></th><th>自転車</th><th>作業区分</th><th>内容</th><th><button class="sort-header" @click="toggleListSort('dashboard','date')">開始日 {{sortLabel('dashboard','date')}} / 完了日</button></th><th><button class="sort-header" @click="toggleListSort('dashboard','status')">状態 {{sortLabel('dashboard','status')}}</button></th></tr></thead><tbody><tr v-for="w in sortByDate(allUpcoming, 'dashboard', x=>x.date, x=>bikes.find(b=>b.id===x.bikeId)?.customer||'', x=>x.status).slice(0,7)" :key="w.id+'-'+w.kind"><td><button class="customer-link" @click="openCustomerDetail(bikes.find(b=>b.id===w.bikeId)?.customer||'')">{{bikes.find(b=>b.id===w.bikeId)?.customer}}</button></td><td>{{bikes.find(b=>b.id===w.bikeId)?.model}}</td><td>{{w.kind}}</td><td>{{w.title}}</td><td><b>{{w.date}}</b><small class="cell-sub">〜 {{w.endDate||'未定'}}</small></td><td><span class="status info">{{w.status}}</span></td></tr></tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2>契約回数の状況</h2><p>オーバーホール・メンテナンス・点検サポートを独立して管理</p></div><input class="search" v-model="searchDashboard" placeholder="顧客・自転車・プランで検索"/><button class="text-btn" @click="setPage('bikes')">契約一覧 →</button></div><div class="table-wrap"><table><thead><tr><th>顧客・自転車</th><th>プラン</th><th>オーバーホール</th><th>メンテナンス</th><th>点検サポート</th><th>契約期間</th></tr></thead><tbody><tr v-for="b in bikes.filter(x=>matches(searchDashboard,x.customer,x.name,x.maker,x.model,planFor(x).name,shops.find(sh=>sh.id===x.shopId)?.name))" :key="b.id"><td><button class="customer-link" @click="openCustomerDetail(b.customer)">{{b.customer}} <small v-if="bikeCountForCustomer(b.customer)>1" class="multi-bike-tag">{{bikeCountForCustomer(b.customer)}}台契約</small></button><small class="cell-sub">{{b.name}} · {{b.maker}} {{b.model}}</small></td><td>{{planFor(b).name}}</td><td>{{remaining(b,'overhaul')}} / {{planFor(b).overhaulCount}}回</td><td>{{remaining(b,'maintenance')}} / {{planFor(b).maintenanceCount}}回</td><td>{{remaining(b,'inspection')}} / {{planFor(b).inspectionCount}}回</td><td>{{b.contractStart}}〜{{b.contractEnd}}</td></tr></tbody></table></div></section></template>

<template v-else-if="page==='contracts'"><div class="page-heading"><div><p class="eyebrow">ANNUAL CONTRACT REGISTRATION</p><h1>年間契約登録</h1><p class="sub">顧客・自転車・プラン・担当店舗を指定して年間契約を登録します。</p></div><button class="primary" @click="showContractModal=true">＋ 年間契約を登録</button></div><div class="callout"><b>契約受付期限：12月31日</b><p>契約日は11月中でも登録できます。契約期間は12月1日〜翌年11月30日です。契約登録後は、最初にオーバーホールの受付日と実施予定日を決めます。</p></div><section class="panel"><div class="panel-head"><div><h2>登録済みの年間契約</h2><p>顧客・自転車ごとの契約内容は一覧で確認できます。</p></div><button class="outline" @click="setPage('bikes')">契約一覧を表示</button></div><div class="table-wrap"><table><thead><tr><th>顧客</th><th>自転車</th><th>プラン</th><th>契約期間</th><th>担当店舗</th></tr></thead><tbody><tr v-for="b in bikes" :key="b.id"><td><button class="customer-link" @click="openCustomerDetail(b.customer)">{{b.customer}}</button></td><td>{{b.name}}<small class="cell-sub">{{b.maker}} {{b.model}}</small></td><td>{{planFor(b).name}}</td><td>{{b.contractStart}}〜{{b.contractEnd}}</td><td>{{shops.find(x=>x.id===b.shopId)?.name}}</td></tr></tbody></table></div></section></template><template v-else-if="page==='shops'"><div class="page-heading"><div><p class="eyebrow">MULTI-STORE MANAGEMENT</p><h1>店舗・受付担当者管理</h1><p class="sub">複数店舗と、店舗ごとの受付担当者を管理します。</p></div><div class="heading-actions"><button class="outline" @click="showStaffModal=true">＋ 担当者を登録</button><button class="primary" @click="showShopModal=true">＋ 店舗を登録</button></div></div><section class="panel"><div class="panel-head"><div><h2>登録店舗一覧</h2><p>{{shops.length}}店舗</p></div><input class="search" v-model="searchShops" placeholder="店舗名・住所・電話・担当者で検索"/></div><div class="table-wrap"><table><thead><tr><th>店舗名</th><th>住所</th><th>電話番号</th><th>受付担当者</th></tr></thead><tbody><tr v-for="shop in shops.filter(x=>matches(searchShops,x.name,x.address,x.phone,staff.filter(y=>y.shopId===x.id).map(y=>y.name).join(' ')))" :key="shop.id"><td><b>{{shop.name}}</b></td><td>{{shop.address}}</td><td>{{shop.phone}}</td><td>{{staff.filter(x=>x.shopId===shop.id).map(x=>x.name).join('、')||'未登録'}}</td></tr></tbody></table></div></section></template><template v-else-if="page==='plans'"><div class="page-heading"><div><p class="eyebrow">PLAN MASTER</p><h1>プラン設定</h1><p class="sub">プランごとにオーバーホール・メンテナンス・点検サポートの回数を別々に設定します。</p></div><button class="primary" @click="showPlanModal=true">＋ プランを追加</button></div><div class="callout"><b>回数枠はそれぞれ独立</b><p>メンテナンスを実施しても点検サポートの回数は減りません。契約終了時の残回数は失効し、翌年度への繰越はありません。</p></div><div class="section-grid"><section v-for="p in plans" :key="p.id" class="panel"><div class="panel-head"><div><h2>{{p.name}}</h2><p>年間契約プラン</p></div><span class="status success">有効</span></div><div class="detail-grid"><div><label>オーバーホール</label><b class="large">{{p.overhaulCount}}回</b></div><div><label>メンテナンス</label><b class="large">{{p.maintenanceCount}}回</b></div><div><label>点検サポート</label><b class="large">{{p.inspectionCount}}回</b></div></div></section></div><div class="panel-foot">※ 追加したプランは年間契約登録画面のプラン選択肢に反映されます。既存契約のプラン内容は、新しいプランを追加しても変更されません。</div></template><template v-else-if="page==='bikes'"><div class="page-heading"><div><p class="eyebrow">CUSTOMERS & BICYCLES</p><h1>顧客・自転車・契約管理</h1><p class="sub">自転車ごとに年間プランと契約期間、各サービスの残回数を管理します。</p></div><button class="primary" @click="setPage('contracts')">＋ 契約を登録</button></div><section class="panel"><div class="panel-head"><div><h2>年間契約一覧</h2><p>{{customers.length}}名・{{bikes.length}}台の自転車が登録されています</p></div><input class="search" v-model="searchBikes" placeholder="顧客・自転車・プラン・店舗で検索"/><span class="count">契約期間：12月1日〜翌年11月30日</span></div><div class="table-wrap"><table><thead><tr><th><button class="sort-header" @click="toggleListSort('bikes','customer')">顧客・自転車 {{sortLabel('bikes','customer')}}</button></th><th>契約プラン</th><th>契約期間</th><th>担当店舗・受付</th><th>OH残</th><th>メンテ残</th><th>点検残</th><th></th></tr></thead><tbody><tr v-for="b in sortByDate(bikes.filter(x=>matches(searchBikes,x.customer,x.name,x.maker,x.model,x.serial,planFor(x).name,shops.find(sh=>sh.id===x.shopId)?.name,x.receptionist)), 'bikes', x=>x.contractStart, x=>x.customer)" :key="b.id"><td><button class="customer-link" @click="openCustomerDetail(b.customer)">{{b.customer}} <small v-if="bikeCountForCustomer(b.customer)>1" class="multi-bike-tag">{{bikeCountForCustomer(b.customer)}}台契約</small></button><small class="cell-sub">{{b.name}} · {{b.maker}} {{b.model}}</small></td><td>{{planFor(b).name}}</td><td>{{b.contractStart}}〜{{b.contractEnd}}</td><td>{{shops.find(x=>x.id===b.shopId)?.name}} / {{b.receptionist}}</td><td>{{remaining(b,'overhaul')}}/{{planFor(b).overhaulCount}}</td><td>{{remaining(b,'maintenance')}}/{{planFor(b).maintenanceCount}}</td><td>{{remaining(b,'inspection')}}/{{planFor(b).inspectionCount}}</td><td><button class="outline small" @click="selectedBikeId=b.id">詳細</button></td></tr></tbody></table></div></section><section class="panel detail-panel"><div class="panel-head"><div><h2>契約詳細</h2><p>選択した自転車の契約回数</p></div><select v-model.number="selectedBikeId"><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.name}}</option></select></div><div class="detail-grid"><div><label>顧客</label><b>{{selectedBike.customer}}</b></div><div><label>自転車</label><b>{{selectedBike.maker}} {{selectedBike.model}}</b></div><div><label>プラン</label><b>{{planFor(selectedBike).name}}</b></div><div><label>契約期間</label><b>{{selectedBike.contractStart}}〜{{selectedBike.contractEnd}}</b></div><div><label>オーバーホール残</label><b class="remaining large">{{remaining(selectedBike,'overhaul')}}回</b></div><div><label>メンテナンス残</label><b class="remaining large">{{remaining(selectedBike,'maintenance')}}回</b></div><div><label>点検サポート残</label><b class="remaining large">{{remaining(selectedBike,'inspection')}}回</b></div><div><label>OH完了日</label><b>{{selectedBike.overhaulCompleted||'未実施'}}</b></div></div></section></template>

<template v-else-if="page==='overhaul'"><div class="page-heading"><div><p class="eyebrow">OVERHAUL MANAGEMENT</p><h1>オーバーホール</h1><p class="sub">年間プランに含まれるオーバーホールの予定・実績を管理します。</p></div></div><div class="callout"><b>受付期限：契約開始年の12月31日 ／ 基本実施期間：契約開始年11月1日〜翌年2月末</b><p>オーバーホールの受付は12月末まで可能で、11月中の契約・受付・実施もシステム上登録できます。実施は契約開始年の11月から翌年2月末までです。オーバーホールとメンテナンスは同じ年間プランに含まれます。完了日は記録しますが、その日から一定間隔でメンテナンス予定を自動生成することはありません。</p></div><div class="list-toolbar"><span class="muted">予定・実績の一覧から作業状況を確認できます。</span><button class="primary" @click="showOverhaulModal=true">＋ オーバーホールを登録</button></div><section class="panel"><div class="panel-head"><div><h2>オーバーホール予定・実績</h2><p>実施完了時にオーバーホール回数を消費</p></div><select class="search" v-model.number="selectedBikeFilter"><option :value="null">すべての自転車</option><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.name}}</option></select><input class="search" v-model="searchOverhauls" placeholder="顧客・自転車・予定名・店舗で検索"/><span class="count">{{overhauls.filter(x=>!selectedBikeFilter||x.bikeId===selectedBikeFilter).length}}件</span></div><div class="table-wrap"><table><thead><tr><th><button class="sort-header" @click="toggleListSort('overhaul','customer')">顧客 {{sortLabel('overhaul','customer')}}</button></th><th>自転車</th><th>作業内容</th><th><button class="sort-header" @click="toggleListSort('overhaul','date')">開始日 {{sortLabel('overhaul','date')}}</button> / 完了日</th><th><button class="sort-header" @click="toggleListSort('overhaul','status')">状態 {{sortLabel('overhaul','status')}}</button></th><th>プラン残回数</th><th>操作</th></tr></thead><tbody><tr v-for="w in sortByDate(overhauls.filter(x=>{const b=bikes.find(y=>y.id===x.bikeId);return (!selectedBikeFilter||x.bikeId===selectedBikeFilter)&&matches(searchOverhauls,b?.customer,b?.name,b?.maker,b?.model,x.date,x.status,x.title,x.detail,shops.find(sh=>sh.id===x.shopId)?.name,x.receptionist)}), 'overhaul', x=>x.date, x=>bikes.find(b=>b.id===x.bikeId)?.customer||'', x=>x.status)" :key="w.id"><td><button class="customer-link" @click="openCustomerDetail(bikes.find(b=>b.id===w.bikeId)?.customer||'')">{{bikes.find(b=>b.id===w.bikeId)?.customer}}</button></td><td>{{bikes.find(b=>b.id===w.bikeId)?.model}}</td><td><b>{{w.title}}</b><small class="cell-sub">{{w.detail}}</small></td><td>{{w.date}}<small class="cell-sub">〜 {{w.endDate||'未定'}}</small></td><td><span class="status info">{{w.status}}</span></td><td>{{remaining(bikes.find(b=>b.id===w.bikeId)!,'overhaul')}}回</td><td><button v-if="w.status!=='完了'" class="outline small" @click="openEdit('overhaul',w)">編集</button> <button v-if="w.status==='予定'||w.status==='予約済み'||w.status==='案内済み'" class="outline small" @click="startWork('overhaul',w)">作業開始</button> <button v-if="w.status==='作業中'" class="primary small" @click="startCompletion('overhaul',w)">完了登録</button><span v-if="w.status==='完了'" class="done">✓ 完了</span></td></tr></tbody></table></div></section></template>

<template v-else-if="page==='maintenance'"><div class="page-heading"><div><p class="eyebrow">MAINTENANCE PLANNING</p><h1>メンテナンス計画</h1><p class="sub">顧客の目標イベントに合わせてスタッフが実施計画を作成します。</p></div></div><div class="callout"><b>固定周期ではなく、目標イベントに合わせた計画</b><p>2か月おきの自動生成は行いません。メインイベントの日程・目標・車体の状態を踏まえて必要なタイミングで計画します。実施完了時のみメンテナンス回数を消費します。</p></div><div class="list-toolbar"><span class="muted">計画は登録後、この一覧に表示されます。</span><button class="primary" @click="showMaintenanceModal=true">＋ メンテナンス計画を追加</button></div><section class="panel"><div class="panel-head"><div><h2>メンテナンス計画一覧</h2><p>予定・案内・予約は回数を消費しません</p></div><select class="search" v-model.number="selectedBikeFilter"><option :value="null">すべての自転車</option><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.name}}</option></select><input class="search" v-model="searchMaintenance" placeholder="顧客・自転車・計画名・担当者で検索"/><span class="count">{{maintenance.filter(x=>!selectedBikeFilter||x.bikeId===selectedBikeFilter).length}}件</span></div><div class="table-wrap"><table><thead><tr><th><button class="sort-header" @click="toggleListSort('maintenance','customer')">顧客 {{sortLabel('maintenance','customer')}}</button></th><th>自転車</th><th>計画・作業内容</th><th><button class="sort-header" @click="toggleListSort('maintenance','date')">開始日 {{sortLabel('maintenance','date')}}</button> / 完了日</th><th><button class="sort-header" @click="toggleListSort('maintenance','status')">状態 {{sortLabel('maintenance','status')}}</button></th><th>プラン残回数</th><th>受付担当</th><th>操作</th></tr></thead><tbody><tr v-for="w in sortByDate(maintenance.filter(x=>{const b=bikes.find(y=>y.id===x.bikeId);return (!selectedBikeFilter||x.bikeId===selectedBikeFilter)&&matches(searchMaintenance,b?.customer,b?.name,b?.maker,b?.model,x.date,x.status,x.title,x.detail,shops.find(sh=>sh.id===x.shopId)?.name,x.receptionist)}), 'maintenance', x=>x.date, x=>bikes.find(b=>b.id===x.bikeId)?.customer||'', x=>x.status)" :key="w.id"><td><button class="customer-link" @click="openCustomerDetail(bikes.find(b=>b.id===w.bikeId)?.customer||'')">{{bikes.find(b=>b.id===w.bikeId)?.customer}}</button></td><td>{{bikes.find(b=>b.id===w.bikeId)?.model}}</td><td><b>{{w.title}}</b><small class="cell-sub">{{w.detail}}</small></td><td><b>{{w.date}}</b><small class="cell-sub">〜 {{w.endDate||'未定'}}</small></td><td><select v-if="w.status!=='完了'" class="status-select" v-model="w.status"><option>予定</option><option>案内待ち</option><option>案内済み</option><option>予約済み</option><option>作業中</option><option>キャンセル</option></select><span v-else class="done">✓ 完了</span></td><td>{{remaining(bikes.find(b=>b.id===w.bikeId)!,'maintenance')}}回</td><td>{{shops.find(x=>x.id===w.shopId)?.name}} / {{w.receptionist}}</td><td><button v-if="w.status!=='完了'" class="outline small" @click="openEdit('maintenance',w)">編集</button> <button v-if="w.status==='予定'||w.status==='予約済み'||w.status==='案内済み'" class="outline small" @click="startWork('maintenance',w)">作業開始</button> <button v-if="w.status==='作業中'" class="primary small" @click="startCompletion('maintenance',w)">完了登録</button><span v-if="w.status==='完了'" class="done">✓ 完了</span></td></tr></tbody></table></div></section></template>

<template v-else-if="page==='events'"><div class="page-heading"><div><p class="eyebrow">TARGET EVENTS & INSPECTIONS</p><h1>目標イベント・点検サポート</h1><p class="sub">顧客のメインイベントと、その前に行う点検サポートを管理します。</p></div></div><div class="callout"><b>点検サポートはメンテナンスとは別枠</b><p>点検サポートの実施完了時にのみ、プランの点検回数を1回消費します。メンテナンス回数とは相互に影響しません。</p></div><div class="list-toolbar"><span class="muted">イベント・点検予定を登録すると一覧に反映されます。</span><button class="primary" @click="showEventModal=true">＋ イベント・点検を登録</button></div><section class="panel"><div class="panel-head"><div><h2>イベント・点検サポート一覧</h2><p>点検完了時に点検サポート枠を消費</p></div><select class="search" v-model.number="selectedBikeFilter"><option :value="null">すべての自転車</option><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.name}}</option></select><input class="search" v-model="searchEvents" placeholder="イベント名・顧客・自転車・店舗で検索"/></div><div class="table-wrap"><table><thead><tr><th><button class="sort-header" @click="toggleListSort('events','customer')">顧客 {{sortLabel('events','customer')}}</button></th><th>自転車</th><th>イベント名</th><th>開催日</th><th><button class="sort-header" @click="toggleListSort('events','date')">点検開始日 {{sortLabel('events','date')}}</button> / 完了日</th><th><button class="sort-header" @click="toggleListSort('events','status')">状態 {{sortLabel('events','status')}}</button></th><th>プラン残回数</th><th>受付担当</th><th>操作</th></tr></thead><tbody><tr v-for="e in sortByDate(eventChecks.filter(x=>{const b=bikes.find(y=>y.id===x.bikeId);return (!selectedBikeFilter||x.bikeId===selectedBikeFilter)&&matches(searchEvents,x.name,x.memo,x.eventDate,x.inspectionDate,x.status,b?.customer,b?.name,b?.maker,b?.model,shops.find(sh=>sh.id===x.shopId)?.name,x.receptionist)}), 'events', x=>x.inspectionDate, x=>bikes.find(b=>b.id===x.bikeId)?.customer||'', x=>x.status)" :key="e.id"><td>{{bikes.find(b=>b.id===e.bikeId)?.customer}}</td><td>{{bikes.find(b=>b.id===e.bikeId)?.model}}</td><td><b>{{e.name}}</b><small class="cell-sub">{{e.memo}}</small></td><td>{{e.eventDate}}</td><td>{{e.inspectionDate}}<small class="cell-sub">〜 {{e.endDate||'未定'}}</small></td><td><span class="status info">{{e.status}}</span></td><td>{{remaining(bikes.find(b=>b.id===e.bikeId)!,'inspection')}}回</td><td>{{shops.find(x=>x.id===e.shopId)?.name}} / {{e.receptionist}}</td><td><button v-if="e.status!=='完了'" class="outline small" @click="openEdit('event',e)">編集</button> <button v-if="e.status==='予定'||e.status==='予約済み'||e.status==='案内済み'" class="outline small" @click="startWork('event',e)">作業開始</button> <button v-if="e.status==='作業中'" class="primary small" @click="startCompletion('event',e)">完了登録</button><span v-if="e.status==='完了'" class="done">✓ 完了</span></td></tr></tbody></table></div></section></template>

<template v-else-if="page==='history'"><div class="page-heading"><div><p class="eyebrow">SERVICE HISTORY</p><h1>メンテナンス履歴</h1><p class="sub">自転車ごとのオーバーホール・メンテナンス・点検サポートの履歴です。</p></div><select class="search" v-model.number="selectedBikeId"><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.name}}</option></select></div><section class="panel"><div class="panel-head"><div><h2>{{selectedBike.maker}} {{selectedBike.model}}</h2><p>{{selectedBike.customer}} 様の作業履歴</p></div><input class="search" v-model="searchHistory" placeholder="作業区分・作業名・詳細で検索"/><span class="count">{{histories.filter(h=>h.bikeId===selectedBikeId).length}}件</span></div><div class="table-wrap"><table><thead><tr><th><button class="sort-header" @click="toggleListSort('history','date')">開始日 {{sortLabel('history','date')}} / 完了日 {{sortLabel('history','date')}}</button></th><th>作業区分</th><th>作業内容</th><th>作業時のメモ</th><th>詳細</th></tr></thead><tbody><tr v-for="h in sortByDate(histories.filter(x=>x.bikeId===selectedBikeId&&matches(searchHistory,x.date,x.category,x.title,x.detail,x.memo)), 'history', x=>x.date)" :key="h.id"><td><b>{{h.startDate||h.date}}</b><small class="cell-sub">〜 {{h.date}}</small></td><td>{{h.category}}</td><td>{{h.title}}</td><td class="memo-cell">{{h.memo||'—'}}</td><td>{{h.detail}}</td></tr></tbody></table></div></section></template>

<template v-else-if="page==='messages'"><div class="page-heading"><div><p class="eyebrow">COMMUNICATION</p><h1>連絡・メール管理</h1><p class="sub">イベント・メンテナンス予定に関する顧客連絡を管理します。</p></div><button class="primary" @click="showMail=true">✉ メールを作成</button></div><section class="panel"><div class="panel-head"><div><h2>案内待ちのメンテナンス・点検</h2><p>顧客への連絡が必要な予定</p></div><input class="search" v-model="searchMessages" placeholder="顧客・自転車・予定日・区分で検索"/><span class="status warning">{{pendingCount}}件</span></div><div class="table-wrap"><table><thead><tr><th><button class="sort-header" @click="toggleListSort('messages','customer')">顧客 {{sortLabel('messages','customer')}}</button></th><th>自転車</th><th>作業区分</th><th>予定内容</th><th><button class="sort-header" @click="toggleListSort('messages','date')">予定日 {{sortLabel('messages','date')}}</button></th><th>操作</th></tr></thead><tbody><tr v-for="w in sortByDate([...maintenance.filter(x=>x.status==='案内待ち').map(x=>({...x,kind:'メンテナンス'})),...eventChecks.filter(x=>x.status==='案内待ち').map(x=>({...x,date:x.inspectionDate,title:x.name,kind:'点検サポート'}))].filter(x=>{const b=bikes.find(y=>y.id===x.bikeId);return matches(searchMessages,b?.customer,b?.model,x.date,x.title,x.kind)}), 'messages', x=>x.date, x=>bikes.find(b=>b.id===x.bikeId)?.customer||'', x=>x.status)" :key="w.id"><td><button class="customer-link" @click="openCustomerDetail(bikes.find(b=>b.id===w.bikeId)?.customer||'')">{{bikes.find(b=>b.id===w.bikeId)?.customer}}</button></td><td>{{bikes.find(b=>b.id===w.bikeId)?.model}}</td><td>{{w.kind}}</td><td>{{w.title}}</td><td>{{w.date}}</td><td><button class="outline small" @click="mailTarget=bikes.find(b=>b.id===w.bikeId)?.customer||'';mailKind=w.kind+'のご案内';showMail=true">内容確認</button></td></tr></tbody></table></div></section></template>

<template v-else><div class="page-heading"><div><p class="eyebrow">CUSTOMER PORTAL</p><h1>マイページ</h1><p class="sub">ご登録のロードバイクと年間プランをご確認いただけます。</p></div><span class="customer-welcome">山田 太郎 様</span></div><section class="panel"><div class="panel-head"><div><h2>ご契約中のロードバイク</h2><p>山田 太郎 様 · {{customerBikes.length}}台をご契約中</p></div><input class="search" v-model="searchMyPage" placeholder="自転車・プランで検索"/><span class="status success">契約中</span></div><div v-for="b in customerBikes.filter(x=>matches(searchMyPage,x.name,x.maker,x.model,planFor(x).name))" :key="b.id" class="customer-bike"><div class="bike-symbol">🚴</div><div class="equipment-details"><b>{{b.maker}} {{b.model}}</b><small>{{planFor(b).name}} · 契約期間 {{b.contractStart}}〜{{b.contractEnd}}</small><small>オーバーホール残 {{remaining(b,'overhaul')}}回</small><small>メンテナンス残 {{remaining(b,'maintenance')}} / {{planFor(b).maintenanceCount}}回</small><small>点検サポート残 {{remaining(b,'inspection')}} / {{planFor(b).inspectionCount}}回</small></div></div></section><section class="panel"><div class="panel-head"><div><h2>メンテナンス・点検予定</h2><p>目標イベントに合わせたサポート予定</p></div></div><div class="table-wrap"><table><thead><tr><th>対象自転車</th><th>作業区分</th><th>内容</th><th><button class="sort-header" @click="toggleListSort('mypage','date')">開始日 {{sortLabel('mypage','date')}} / 完了日</button></th><th><button class="sort-header" @click="toggleListSort('mypage','status')">状態 {{sortLabel('mypage','status')}}</button></th></tr></thead><tbody><tr v-for="w in sortByDate([...maintenance.filter(x=>customerBikes.some(b=>b.id===x.bikeId)),...eventChecks.filter(x=>customerBikes.some(b=>b.id===x.bikeId)).map(x=>({...x,date:x.inspectionDate,title:x.name,kind:'点検サポート'}))], 'mypage', x=>x.date, x=>bikes.find(b=>b.id===x.bikeId)?.customer||'', x=>x.status)" :key="w.id"><td><b>{{bikes.find(b=>b.id===w.bikeId)?.maker}} {{bikes.find(b=>b.id===w.bikeId)?.model}}</b><small>{{bikes.find(b=>b.id===w.bikeId)?.name}}</small></td><td>{{'kind' in w?w.kind:'メンテナンス'}}</td><td>{{w.title}}</td><td>{{w.date}}〜{{w.endDate||'未定'}}</td><td>{{w.status}}</td></tr></tbody></table></div></section></template>
</div></main></div>
<div v-if="showCustomerDetail" class="modal-backdrop" @click.self="showCustomerDetail=false"><div class="modal modal-wide customer-detail-modal"><div class="modal-head"><div><p class="eyebrow">CUSTOMER PROFILE</p><h2>{{selectedCustomerName}} 様の顧客情報</h2><p class="sub">管理画面から顧客マイページと同等の契約・予定・履歴を確認できます。</p></div><button class="close" @click="showCustomerDetail=false">×</button></div><section class="customer-profile-summary"><div><label>顧客名</label><b>{{selectedCustomerName}}</b></div><div><label>メールアドレス</label><b>{{selectedCustomer?.email||'未登録'}}</b></div><div><label>契約自転車</label><b>{{selectedCustomerBikes.length}}台</b></div></section><section class="customer-profile-section"><div class="panel-head"><div><h3>契約中の自転車・年間プラン</h3><p>自転車ごとの契約期間とサービス残回数</p></div></div><div v-for="b in selectedCustomerBikes" :key="b.id" class="customer-profile-bike"><div class="customer-profile-bike-title"><b>{{b.name}} — {{b.maker}} {{b.model}}</b><span class="status success">契約中</span></div><div class="customer-bike-actions"><button class="outline small" @click="openCustomerBikePage('maintenance',b.id)">この自転車の予定を管理</button><button class="outline small" @click="openCustomerBikePage('history',b.id)">この自転車の作業履歴</button></div><div class="detail-grid"><div><label>プラン</label><b>{{planFor(b).name}}</b></div><div><label>契約期間</label><b>{{b.contractStart}}〜{{b.contractEnd}}</b></div><div><label>担当店舗・受付</label><b>{{shops.find(x=>x.id===b.shopId)?.name}} / {{b.receptionist}}</b></div><div><label>オーバーホール残</label><b class="remaining">{{remaining(b,'overhaul')}} / {{planFor(b).overhaulCount}}回</b></div><div><label>メンテナンス残</label><b class="remaining">{{remaining(b,'maintenance')}} / {{planFor(b).maintenanceCount}}回</b></div><div><label>点検サポート残</label><b class="remaining">{{remaining(b,'inspection')}} / {{planFor(b).inspectionCount}}回</b></div></div></div><div v-if="!selectedCustomerBikes.length" class="empty-state">契約中の自転車はありません。</div></section><section class="customer-profile-section"><div class="panel-head"><div><h3>メンテナンス・点検予定</h3><p>対象自転車・作業期間・状態</p></div></div><div class="table-wrap"><table><thead><tr><th>対象自転車</th><th>作業区分</th><th>内容</th><th>開始日〜完了日</th><th>状態</th><th>操作</th></tr></thead><tbody><tr v-for="w in selectedCustomerWorks" :key="w.kind+'-'+w.id"><td>{{selectedCustomerBikes.find(b=>b.id===w.bikeId)?.name}}</td><td>{{w.kind}}</td><td>{{w.title}}</td><td>{{w.date}}〜{{w.endDate||'未定'}}</td><td><span class="status info">{{w.status}}</span></td><td><button class="outline small" @click="openCustomerWork(w)">管理画面で開く</button></td></tr><tr v-if="!selectedCustomerWorks.length"><td colspan="6" class="empty-state">予定は登録されていません。</td></tr></tbody></table></div></section><section class="customer-profile-section"><div class="panel-head"><div><h3>作業履歴</h3><p>完了した作業と記録メモ</p></div></div><div class="table-wrap"><table><thead><tr><th>実施日</th><th>対象自転車</th><th>作業区分</th><th>作業内容</th><th>メモ</th></tr></thead><tbody><tr v-for="h in selectedCustomerHistories" :key="h.id"><td>{{h.date}}</td><td>{{selectedCustomerBikes.find(b=>b.id===h.bikeId)?.name}}</td><td>{{h.category}}</td><td>{{h.title}}</td><td>{{h.memo||'—'}}</td></tr><tr v-if="!selectedCustomerHistories.length"><td colspan="5" class="empty-state">作業履歴はありません。</td></tr></tbody></table></div></section><div class="modal-actions"><button class="outline" @click="showCustomerDetail=false">閉じる</button></div></div></div>
<div v-if="showContractModal" class="modal-backdrop" @click.self="showContractModal=false"><div class="modal modal-wide"><div class="modal-head"><div><p class="eyebrow">NEW ANNUAL CONTRACT</p><h2>年間契約を登録</h2></div><button class="close" @click="showContractModal=false">×</button></div><div class="detail-grid"><div><label>顧客</label><select v-model="contractForm.customer"><option v-for="c in customers" :key="c.name">{{c.name}}</option></select></div><div><label>自転車名</label><input v-model="contractForm.bikeName"/></div><div><label>メーカー</label><input v-model="contractForm.maker"/></div><div><label>モデル</label><input v-model="contractForm.model"/></div><div><label>年式</label><input v-model.number="contractForm.year" type="number"/></div><div><label>車体番号</label><input v-model="contractForm.serial"/></div><div><label>契約プラン</label><select v-model.number="contractForm.planId"><option v-for="p in plans" :key="p.id" :value="p.id">{{p.name}}（OH {{p.overhaulCount}} / メンテ {{p.maintenanceCount}} / 点検 {{p.inspectionCount}}）</option></select></div><div><label>契約受付日</label><input v-model="contractForm.applicationDate" type="date"/></div><div><label>契約開始日</label><input v-model="contractForm.start" type="date"/></div><div><label>担当店舗</label><select v-model.number="contractForm.shopId"><option v-for="shop in shops" :key="shop.id" :value="shop.id">{{shop.name}}</option></select></div><div><label>受付担当者</label><select v-model="contractForm.receptionist"><option v-for="person in staff.filter(x=>x.shopId===contractForm.shopId)" :key="person.id">{{person.name}}</option></select></div></div><div class="modal-note">契約受付期限は契約開始年の12月31日。契約期間は12月1日〜翌年11月30日です。</div><div class="modal-actions"><button class="outline" @click="showContractModal=false">キャンセル</button><button class="primary" @click="addContract">契約を登録してOH予定へ進む</button></div></div></div>
<div v-if="showShopModal" class="modal-backdrop" @click.self="showShopModal=false"><div class="modal"><div class="modal-head"><div><p class="eyebrow">NEW STORE</p><h2>店舗を登録</h2></div><button class="close" @click="showShopModal=false">×</button></div><label>店舗名</label><input v-model="newShopName" placeholder="例：大阪店"/><label>住所</label><input v-model="newShopAddress" placeholder="住所"/><label>電話番号</label><input v-model="newShopPhone" placeholder="電話番号"/><div class="modal-actions"><button class="outline" @click="showShopModal=false">キャンセル</button><button class="primary" @click="addShop">店舗を登録</button></div></div></div>
<div v-if="showStaffModal" class="modal-backdrop" @click.self="showStaffModal=false"><div class="modal"><div class="modal-head"><div><p class="eyebrow">NEW STAFF</p><h2>受付担当者を登録</h2></div><button class="close" @click="showStaffModal=false">×</button></div><label>所属店舗</label><select v-model.number="newStaffShop"><option v-for="shop in shops" :key="shop.id" :value="shop.id">{{shop.name}}</option></select><label>担当者名</label><input v-model="newStaffName" placeholder="担当者名"/><div class="modal-actions"><button class="outline" @click="showStaffModal=false">キャンセル</button><button class="primary" @click="addStaff">担当者を登録</button></div></div></div>
<div v-if="showPlanModal" class="modal-backdrop" @click.self="showPlanModal=false"><div class="modal"><div class="modal-head"><div><p class="eyebrow">NEW PLAN</p><h2>プランを追加</h2></div><button class="close" @click="showPlanModal=false">×</button></div><label>プラン名</label><input v-model="newPlan.name" placeholder="例：競技者向けプラン"/><label>オーバーホール回数</label><input v-model.number="newPlan.overhaulCount" type="number" min="0" step="1"/><label>メンテナンス回数</label><input v-model.number="newPlan.maintenanceCount" type="number" min="0" step="1"/><label>点検サポート回数</label><input v-model.number="newPlan.inspectionCount" type="number" min="0" step="1"/><div class="modal-note">回数はそれぞれ独立して設定します。</div><div class="modal-actions"><button class="outline" @click="showPlanModal=false">キャンセル</button><button class="primary" @click="addPlan">プランを追加</button></div></div></div>
<div v-if="showOverhaulModal" class="modal-backdrop" @click.self="showOverhaulModal=false"><div class="modal modal-wide"><div class="modal-head"><div><p class="eyebrow">NEW OVERHAUL</p><h2>オーバーホールを登録</h2></div><button class="close" @click="showOverhaulModal=false">×</button></div><div class="detail-grid"><div><label>顧客・自転車</label><select v-model.number="newOverhaulBike"><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.model}}</option></select></div><div><label>受付日</label><input v-model="newOverhaulReceptionDate" type="date"/></div><div><label>作業開始予定日</label><input v-model="newOverhaulDate" type="date"/></div><div><label>作業完了予定日</label><input v-model="newOverhaulEndDate" type="date"/></div><div><label>作業名</label><input v-model="newOverhaulTitle"/></div><div><label>作業内容</label><input v-model="newOverhaulDetail"/></div></div><div class="modal-note">受付期限は契約開始年の12月31日。実施期間は契約開始年11月〜翌年2月末です。残回数：{{remaining(bikes.find(b=>b.id===newOverhaulBike)!,'overhaul')}}回</div><div class="modal-actions"><button class="outline" @click="showOverhaulModal=false">キャンセル</button><button class="primary" @click="addOverhaul">オーバーホールを登録</button></div></div></div>
<div v-if="showMaintenanceModal" class="modal-backdrop" @click.self="showMaintenanceModal=false"><div class="modal modal-wide"><div class="modal-head"><div><p class="eyebrow">NEW MAINTENANCE</p><h2>メンテナンス計画を追加</h2></div><button class="close" @click="showMaintenanceModal=false">×</button></div><div class="detail-grid"><div><label>顧客・自転車</label><select v-model.number="newWorkBike"><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.model}}</option></select></div><div><label>作業開始予定日</label><input v-model="newWorkDate" type="date"/></div><div><label>作業完了予定日</label><input v-model="newWorkEndDate" type="date"/></div><div><label>計画名</label><input v-model="newWorkTitle"/></div><div><label>作業内容</label><input v-model="newWorkDetail"/></div></div><div class="modal-note">メンテナンス残回数：{{remaining(bikes.find(b=>b.id===newWorkBike)!,'maintenance')}}回</div><div class="modal-actions"><button class="outline" @click="showMaintenanceModal=false">キャンセル</button><button class="primary" @click="addMaintenance">計画を登録</button></div></div></div>
<div v-if="showEventModal" class="modal-backdrop" @click.self="showEventModal=false"><div class="modal modal-wide"><div class="modal-head"><div><p class="eyebrow">NEW EVENT & INSPECTION</p><h2>イベント・点検を登録</h2></div><button class="close" @click="showEventModal=false">×</button></div><div class="detail-grid"><div><label>顧客・自転車</label><select v-model.number="newEventBike"><option v-for="b in bikes" :key="b.id" :value="b.id">{{b.customer}} / {{b.model}}</option></select></div><div><label>イベント名</label><input v-model="newEventName" placeholder="例：年間メインイベント"/></div><div><label>イベント開催日</label><input v-model="newEventDate" type="date"/></div><div><label>点検開始予定日</label><input v-model="newInspectionDate" type="date"/></div><div><label>点検完了予定日</label><input v-model="newInspectionEndDate" type="date"/></div></div><div class="modal-note">点検サポート残回数：{{remaining(bikes.find(b=>b.id===newEventBike)!,'inspection')}}回</div><div class="modal-actions"><button class="outline" @click="showEventModal=false">キャンセル</button><button class="primary" @click="addEvent">イベント・点検を登録</button></div></div></div>
<div v-if="completionTarget" class="modal-backdrop" @click.self="completionTarget=null"><div class="modal"><div class="modal-head"><div><p class="eyebrow">WORK COMPLETION</p><h2>作業完了・メモ登録</h2></div><button class="close" @click="completionTarget=null">×</button></div><p class="sub">作業内容や交換部品、調整箇所、次回確認事項などを記録できます。</p><label>作業完了日</label><input v-model="completionDate" type="date"/><label>作業時のメモ</label><textarea v-model="completionMemo" rows="6" placeholder="例：チェーン・スプロケットを洗浄。リアブレーキパッド交換。変速調整済み。次回はタイヤ摩耗を確認。"></textarea><div class="modal-note">メモは作業履歴に保存され、後から「メンテナンス履歴」画面で確認できます。</div><div class="modal-actions"><button class="outline" @click="completionTarget=null">キャンセル</button><button class="primary" @click="confirmCompletion">作業完了として保存</button></div></div></div>
<div v-if="editTarget" class="modal-backdrop" @click.self="editTarget=null"><div class="modal"><div class="modal-head"><div><p class="eyebrow">EDIT SCHEDULE</p><h2>予定の変更</h2></div><button class="close" @click="editTarget=null">×</button></div><label>作業開始日</label><input v-model="editDate" type="date"/><label>作業完了予定日</label><input v-model="editEndDate" type="date"/><label>予定名・イベント名</label><input v-model="editTitle"/><label>内容・メモ</label><input v-model="editDetail"/><label>受付担当者</label><select v-model="editReceptionist"><option v-for="person in staff" :key="person.id">{{person.name}}</option></select><div class="modal-note">開始日・完了予定日を変更できます。完了日は開始日以降にしてください。契約回数は作業完了時のみ消費します。</div><div class="modal-actions"><button class="outline" @click="editTarget=null">キャンセル</button><button class="primary" @click="saveEdit">変更を保存</button></div></div></div>
<div v-if="showMail" class="modal-backdrop" @click.self="showMail=false"><div class="modal"><div class="modal-head"><div><p class="eyebrow">EMAIL PREVIEW</p><h2>メンテナンス案内メール</h2></div><button class="close" @click="showMail=false">×</button></div><label>送信先</label><select v-model="mailTarget"><option v-for="c in customers" :key="c.name">{{c.name}}</option></select><label>件名</label><input v-model="mailKind"/><label>本文</label><div class="mail-body">{{mailTarget}} 様<br><br>いつもご利用いただきありがとうございます。<br>メンテナンス・点検予定についてご案内いたします。<br><br>ご希望の日程がございましたら店舗までご連絡ください。<br><br>今後ともよろしくお願いいたします。</div><div class="modal-note">※ モックのため、実際のメール送信は行われません。</div><div class="modal-actions"><button class="outline" @click="showMail=false">閉じる</button><button class="primary" @click="sendMail">送信（デモ）</button></div></div></div>
</template>
